<script setup lang="ts">import { onMounted, ref } from 'vue'; import { useRouter } from 'vue-router'; import { useAuthStore } from '../stores/auth'; import { ApiError, usersApi } from '../services/api'; import type { Role, User } from '../types/auth'; import ChangePasswordForm from '../components/ChangePasswordForm.vue'; const auth=useAuthStore();const router=useRouter();const dialog=ref(false);const users=ref<User[]>([]);const error=ref('');const roles: {title:string;value:Role}[]=[{title:'Sin permisos',value:'usuario'},{title:'Administrador',value:'administrador'},{title:'Recepcionista',value:'recepcionista'},{title:'Asesor de servicio',value:'asesor_servicio'},{title:'Técnico',value:'tecnico'}];function logout(){auth.logout();router.push('/acceso')}async function load(){if(auth.user?.role!=='administrador')return;try{users.value=await usersApi.list(auth.token)}catch(e){error.value=e instanceof ApiError?e.message:'No fue posible cargar usuarios.'}}async function changeRole(user:User,role:Role){try{const u=await usersApi.updateRole(user.id,role,auth.token);users.value=users.value.map(x=>x.id===u.id?u:x)}catch(e){error.value=e instanceof ApiError?e.message:'No fue posible actualizar.'}}onMounted(load)</script>
<template><v-app><v-app-bar color="primary"><v-app-bar-title><v-icon>mdi-car-wrench</v-icon> Taller Mecánico</v-app-bar-title><v-menu><template #activator="{ props }"><v-btn v-bind="props" prepend-icon="mdi-menu">Menú</v-btn></template><v-list><v-list-item to="/clientes" prepend-icon="mdi-account-group" title="Clientes"/><v-list-item v-if="auth.user?.role==='administrador'" to="/administracion/roles" prepend-icon="mdi-shield-account" title="Roles del sistema"/><v-list-item v-if="['administrador','recepcionista','asesor_servicio'].includes(auth.user?.role ?? '')" to="/administracion/taller" prepend-icon="mdi-store-cog" title="Alta de taller"/></v-list></v-menu><v-btn icon="mdi-lock-reset" @click="dialog=true"/><v-btn icon="mdi-logout" @click="logout"/></v-app-bar><v-main><v-container class="py-10"><v-card class="mb-6" rounded="xl"><v-card-item><v-card-title class="text-h4">Bienvenido, {{auth.user?.full_name}}</v-card-title><v-card-subtitle>Rol: {{auth.user?.role}}</v-card-subtitle></v-card-item><v-card-text>Usa el menú para acceder únicamente a los módulos autorizados para tu cuenta.</v-card-text></v-card><v-card v-if="auth.user?.role==='administrador'" rounded="xl"><v-card-title>Administración de usuarios</v-card-title><v-card-text><v-alert v-if="error" type="error">{{error}}</v-alert><v-table><thead><tr><th>Nombre</th><th>Correo</th><th>Permiso</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td>{{user.full_name}}</td><td>{{user.email}}</td><td><v-select :model-value="user.role" :items="roles" item-title="title" item-value="value" density="compact" hide-details @update:model-value="changeRole(user,$event as Role)"/></td></tr></tbody></v-table></v-card-text></v-card></v-container></v-main><v-dialog v-model="dialog" max-width="540"><v-card><v-card-title>Cambiar contraseña</v-card-title><v-card-text><ChangePasswordForm/></v-card-text><v-card-actions><v-spacer/><v-btn @click="dialog=false">Cerrar</v-btn></v-card-actions></v-card></v-dialog></v-app></template>
